// Content with portions generated by generative AI platform
package org.eclipse.kura.web;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.eclipse.kura.web.session.HttpServletContextHelper;
import org.junit.Test;

/**
 * Feature: the Web Console authentication paths can be accessed without an authenticated session, but do not allocate
 * a session in advance, so that unauthenticated requests cannot allocate unbounded server side state.
 */
public class AuthenticationPathSessionCreationTest extends WebConsoleSessionTestBase {

    private static final String LOGIN_PAGE_PATH = "/admin/auth";
    private static final String PASSWORD_AUTH_PATH = "/admin/login/password";
    private static final String CERT_AUTH_PATH = "/admin/login/cert";
    private static final String SECURED_PATH = "/admin/denali/device";

    private HttpServletContextHelper sessionContext;
    private boolean result;

    @Test
    public void noSessionIsCreatedOnRequestToLoginPage() throws Exception {
        givenConsole();
        givenSessionContext();
        givenRequestTo(LOGIN_PAGE_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
        thenNoSessionIsCreated();
    }

    @Test
    public void noSessionIsCreatedOnRequestToPasswordAuthenticationPath() throws Exception {
        givenConsole();
        givenSessionContext();
        givenRequestTo(PASSWORD_AUTH_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
        thenNoSessionIsCreated();
    }

    @Test
    public void noSessionIsCreatedOnRequestToCertificateAuthenticationPath() throws Exception {
        givenConsole();
        givenSessionContext();
        givenRequestTo(CERT_AUTH_PATH);

        whenSecurityIsHandled();

        thenRequestIsAllowed();
        thenNoSessionIsCreated();
    }

    @Test
    public void requestToSecuredPathWithoutSessionIsRejected() throws Exception {
        givenConsole();
        givenSessionContext();
        givenRequestTo(SECURED_PATH);

        whenSecurityIsHandled();

        thenRequestIsRejectedWith(HttpServletResponse.SC_UNAUTHORIZED);
        thenNoSessionIsCreated();
    }

    private void givenSessionContext() {
        this.sessionContext = new HttpServletContextHelper(this.console.createSessionHandlerChain());
    }

    private void whenSecurityIsHandled() throws IOException {
        this.result = this.sessionContext.handleSecurity(this.request, this.response);
    }

    private void thenRequestIsAllowed() {
        assertTrue("the request should have been accepted", this.result);
    }

    private void thenRequestIsRejectedWith(final int expectedStatus) {
        assertFalse("the request should have been rejected", this.result);
        assertEquals(Integer.valueOf(expectedStatus), this.sentError);
    }

    private void thenNoSessionIsCreated() {
        assertFalse("no session should have been allocated", isSessionAllocated());
    }
}
